export function heroFor(path: string): { src: string; credit?: string; href?: string } | undefined {
  const e = entries[path.replace(/\/$/, '') || '/']
  if (!e) return undefined
  return { src: `/img/hero/${e[0]}.jpg`, credit: e[1], href: e[2] }
}

export const heroImagePaths = Object.keys(entries)

